## Code Example

```javascript
class AssertionStyle {
  assert(actual, expected) { throw new Error('not implemented') }
}
class ClassicAssert extends AssertionStyle {
  assert(actual, expected) { if (actual !== expected) throw new Error('mismatch') }
}
class Runner {
  constructor() { this.styles = new Map() }
  register(name, style) { this.styles.set(name, style) }
  assert(styleName, actual, expected) {
    const style = this.styles.get(styleName)
    style.assert(actual, expected)
  }
}
```

